INSERT INTO feature VALUES('circuit-spiders','rewriting','Spiders on a marked sort','circuit-algebras','partial','unique','dependent provers','A theory sort marked `@[ frobenius ]` carries a special commutative Frobenius algebra. A circuit rule that merges or splits a wire of that sort reads as a diagram: each merge and split is a boxless spider, and the spider canon decides the rule modulo the Frobenius laws, within 720 trials. The same merge on an unmarked sort is refused at the port that two nodes bind. No rule rewrites with the spiders yet.','surface-lowering theory-circuit-algebras','corpus/model/circuit/spiders.gandr corpus/pathological/circuit/spiders-unmarked.gandr corpus/ledger/diagnostics/UndescribedMember.SpiderBudget.gandr corpus/ledger/diagnostics/UndescribedMember.UnwiredDiagram.gandr','corpus/ledger/features/circuit-spiders.gandr','#5741');
